// Failure signatures for the Klara chat widget (see infra/loki_handlers/chat_agent.py):
//   non-200 on either call · timeout > 60s · LLM-failure fallback text · reply < 40 chars.
// Returns [] when healthy so the Telegram node never fires.
const failures = [];

let start = null;
try { start = $('Chat start').first().json; } catch (e) { /* node produced nothing */ }
if (!start) {
  failures.push('chat/start produced no output');
} else if (start.error) {
  failures.push('chat/start error (timeout/network): ' + JSON.stringify(start.error).slice(0, 200));
} else if ((start.statusCode ?? 0) !== 200) {
  failures.push('chat/start HTTP ' + start.statusCode);
} else if (!start.body || !start.body.session_token) {
  failures.push('chat/start returned no session_token');
}

const msg = $input.first().json;
let replyPreview = '';
if (msg.error) {
  failures.push('chat/message error (timeout >60s or network): ' + JSON.stringify(msg.error).slice(0, 200));
} else if ((msg.statusCode ?? 0) !== 200) {
  failures.push('chat/message HTTP ' + msg.statusCode);
} else {
  const reply = (msg.body && msg.body.reply) ? String(msg.body.reply) : '';
  replyPreview = reply.slice(0, 120);
  if (reply.includes('having a technical issue right now')) {
    failures.push('LLM fallback reply detected ("having a technical issue right now") — chat is up but the model call is failing');
  } else if (reply.trim().length < 40) {
    failures.push('suspect short reply (' + reply.trim().length + ' chars): "' + replyPreview + '"');
  }
}

if (failures.length === 0) {
  return [];
}

const alertText =
  'KLARAVEX/CHAT — CRITICAL\n' +
  'Synthetic Klara chat probe FAILED at ' + new Date().toISOString() + '\n\n' +
  failures.map(f => '• ' + f).join('\n') + '\n\n' +
  'Probe: POST api.klaravex.com/api/v1/chat/start → /chat/message (Origin: klaravex.com).\n' +
  'Handler: infra/loki_handlers/chat_agent.py · workflow: [klaravex] chat-probe (hourly :22).';

return [{ json: { alertText, failures } }];
